export function totalsByCategory(entries) {
  const totals = new Map();

  for (const { category, amount } of entries) {
    totals.set(category, (totals.get(category) ?? 0) + amount);
  }

  return Array.from(totals, ([category, total]) => ({ category, total }));
}

