import assert from 'node:assert/strict';
import * as m from './solution.mjs';
assert.deepEqual(m.totalsByCategory([{category:"b",amount:2},{category:"a",amount:4},{category:"b",amount:-1}]), [{category:"b",total:1},{category:"a",total:4}]);
assert.deepEqual(m.totalsByCategory([]), []);
assert.deepEqual(m.totalsByCategory([{category:"__proto__",amount:3},{category:"__proto__",amount:2}]), [{category:"__proto__",total:5}]);
assert.deepEqual(m.totalsByCategory([{category:"x",amount:0}]), [{category:"x",total:0}]);
console.log('PASS 05-totals');

